function tipRosterFromBatches(batches){
 const out=[];
 for(const b of batches||[]){const date=txt(b.date||b.id);if(!date||date<state.from||date>state.to)continue;const seen=new Set();
  /* V1.2.5: Today's Team is the roster truth. ES1.8.5 intentionally keeps old drafts/receipts,
     and records removed names in todayTeamRemoved. Those historical names must never reappear
     as roster-only employees in Server Intelligence. Real Board activity or a real final report
     is still added later by buildRows(), so deleting someone from Today's Team never erases history. */
  const removed=new Set((Array.isArray(b?.todayTeamRemoved)?b.todayTeamRemoved:Object.values(b?.todayTeamRemoved||{})).filter(Boolean).map(n=>idKey(canonical(typeof n==='string'?n:(n?.name||n?.employee||n?.server)))));
  for(const member of batchTeamMembers(b)){const c=canonical(member.name),key=idKey(c);if(!key||removed.has(key)||seen.has(key))continue;const role=member.role||batchDraftRole(b,member.name);if(role&&!/(server|bartender|\bbar\b)/i.test(role))continue;seen.add(key);out.push({date,server:c,rawServer:member.name,role:role||'Server',source:'TIP TEAM'})}
 }
 return out
}
function updateTipStatus(){const el=$('tipStatus');if(!el)return;if(tipFeed.error&&!(tipFeed.reports||tipFeed.batches))el.textContent='ERROR';else if(tipFeed.reports&&tipFeed.batches)el.textContent='LIVE';else if(tipFeed.reports||tipFeed.batches)el.textContent='PARTIAL';else el.textContent='SYNCING'}
function boardSyncState(arc,boards,teamDays){let active=0,evidence=false;for(const d of dateList(state.from,state.to)){const td=teamDays?.[d];if(td&&((Array.isArray(td)&&td.filter(Boolean).length)||(!Array.isArray(td)&&typeof td==='object'&&Object.keys(td).length)))evidence=true;for(const sh of ['AM','PM']){if(state.shift!=='ALL'&&state.shift!==sh)continue;const key=d+'_'+sh,live=boards?.[key],a=arc?.[key];if(live||a)evidence=true;rowsArray(live?.rows).forEach(r=>{if(r&&normName(r.server)&&r.active!==false&&!num(r.cutAt))active++})}}const currentDaily=state.mode==='daily'&&state.from===today()&&state.to===today();return {active,evidence,currentDaily,label:active>0?'LIVE':(currentDaily&&evidence?'SHIFT CLOSED':'LIVE')}}
async function refreshBoard(){const statusEl=$('boardStatus');statusEl.textContent='SYNCING';let arc,boards,teamDays;try{[arc,boards,teamDays]=await Promise.all([fetchJson(BOARD_ROOT+'/analyticsV1.json'),fetchJson(BOARD_ROOT+'/rotationBoardV31.json'),fetchJson(BOARD_ROOT+'/teamDayV1.json').catch(()=>null)])}catch(e){console.error('Board connection:',e);statusEl.textContent='ERROR';return}const sync=boardSyncState(arc,boards,teamDays);try{const events=[],roster=[],duty=[],skips=[];for(const d of dateList(state.from,state.to)){
  roster.push(...boardTeamRoster(teamDays?.[d],d));
  for(const sh of ['AM','PM']){if(state.shift!=='ALL'&&state.shift!==sh)continue;const key=d+'_'+sh,live=boards?.[key],a=arc?.[key];if(live){duty.push(...boardDutyFromBoard(live,d,sh));skips.push(...boardSkipEvents(live,d,sh))}const liveEv=live?boardEvents(live,d,sh):[];if(liveEv.length)events.push(...liveEv);else if(a)events.push(...archiveEvents(a,d,sh))}}
 const cleanRoster=dedupeRoster(roster);const dutyKeys=new Set(duty.map(x=>x.date+'|'+x.shift+'|'+idKey(x.server)));for(const r of cleanRoster){const k=r.date+'|'+r.shift+'|'+idKey(r.server);if(!dutyKeys.has(k))duty.push(rosterDutyFromTeam(r))}
 state.board=events;state.boardRoster=cleanRoster;state.boardDuty=dedupeDuty(duty);state.boardSkips=skips;state.tipRoster=tipRosterFromBatches(state.batches);statusEl.textContent=sync.label;try{rebuild()}catch(e){console.error('Analytics rebuild after Board sync:',e)}}catch(e){console.error('Board data processing:',e);statusEl.textContent=sync.active>0?'LIVE':(sync.currentDaily&&sync.evidence?'SHIFT CLOSED':'DATA ISSUE')}}
function subscribeTips(){for(const u of tipUnsubs){try{u()}catch(e){}}tipUnsubs=[];tipFeed={reports:false,batches:false,error:false};updateTipStatus();if(!auth.currentUser||!profile)return;try{const qr=query(collection(db,'hourlyReports'),where('date','>=',state.from),where('date','<=',state.to));tipUnsubs.push(onSnapshot(qr,s=>{state.tips=s.docs.map(d=>({id:d.id,...d.data()}));tipFeed.reports=true;updateTipStatus();rebuild()},e=>{console.error(e);tipFeed.error=true;updateTipStatus()}));const qb=query(collection(db,'hourlyV1Batches'),where('date','>=',state.from),where('date','<=',state.to));tipUnsubs.push(onSnapshot(qb,s=>{state.batches=s.docs.map(d=>({id:d.id,...d.data()}));state.tipRoster=tipRosterFromBatches(state.batches);tipFeed.batches=true;updateTipStatus();rebuild()},e=>{console.warn('Tip roster feed unavailable:',e);tipFeed.error=true;updateTipStatus()}))}catch(e){console.error(e);tipFeed.error=true;updateTipStatus()}}

function reportHours(r){return num(r.totalHoursWork??r.totalHours??r.hoursWorked??r.hours?.totalHours??(num(r.totalMinutesWork)/60))}
